  "Automatic plays Dolby Vision through the TV player, which switches the screen into Dolby Vision itself, and keeps HDR10 and HLG on the built-in player for its steadier buffering.  Choose TV player for all HDR if HDR pictures look washed out or grey.": "ऑटोमैटिक Dolby Vision को TV प्लेयर से चलाता है, जो स्क्रीन को खुद Dolby Vision में बदल देता है, और HDR10 व HLG को बेहतर बफ़रिंग के लिए बिल्ट-इन प्लेयर पर रखता है।  अगर HDR तस्वीर फीकी या ग्रे दिखे, तो सभी HDR के लिए TV प्लेयर चुनें।",
  "Automatic uses the built-in demuxer for fine buffer control and falls back to the TV player when a server blocks it.  TV player uses the least CPU but ignores buffer settings.": "ऑटोमैटिक बफ़र पर बारीक नियंत्रण के लिए बिल्ट-इन डीमक्सर इस्तेमाल करता है, और सर्वर के रोकने पर TV प्लेयर पर आ जाता है।  TV प्लेयर सबसे कम CPU लेता है, पर बफ़र सेटिंग नहीं मानता।",
  "Automatic uses the network helper: a part of TiviBro that runs in the background on the TV and fetches your channels, guide and streams for the app.  webOS needs it for most providers.  Direct asks the provider straight from the app, which only works with servers that allow it.  Channel lists still load through the helper when it runs, so a big one can't close TiviBro.": "ऑटोमैटिक नेटवर्क हेल्पर इस्तेमाल करता है: यह TiviBro का वह हिस्सा है जो TV पर बैकग्राउंड में चलता है और ऐप के लिए आपके चैनल, गाइड और स्ट्रीम लाता है।  ज़्यादातर प्रोवाइडर के लिए webOS को इसकी ज़रूरत होती है।  डायरेक्ट ऐप से सीधे प्रोवाइडर से पूछता है, जो सिर्फ़ उन सर्वर के साथ चलता है जो इसकी इजाज़त देते हैं।  हेल्पर चल रहा हो तो चैनल लिस्ट फिर भी उसी से लोड होती हैं, ताकि बड़ी लिस्ट से TiviBro बंद न हो।",
  "Automatic, in Dolby Vision": "ऑटोमैटिक, Dolby Vision में",
  "Automatic: the TV's language": "ऑटोमैटिक: TV की भाषा",
