  "Away from home, Plex plays only with Plex Pass (yours or the server owner's) or a Remote Watch Pass.": "घर से बाहर Plex सिर्फ़ Plex Pass (आपका या सर्वर के मालिक का) या Remote Watch Pass के साथ चलता है।",
  "Away from home, Plex plays video only when you or the server's owner have Plex Pass (or a Remote Watch Pass).  At home it's free.": "घर से बाहर Plex वीडियो तभी चलाता है जब आपके या सर्वर के मालिक के पास Plex Pass (या Remote Watch Pass) हो।  घर पर यह मुफ़्त है।",
