  "Channels and groups named Adult, XXX, 18+, Porn, Erotic and the like, in several languages (\"Adult Swim\" stays).  Gone from the guide, every list, Search and the phone app.  No PIN needed.": "Adult, XXX, 18+, Porn, Erotic जैसे नामों वाले चैनल और ग्रुप, कई भाषाओं में (\"Adult Swim\" रहता है)।  गाइड, हर लिस्ट, खोजें और फ़ोन ऐप से गायब।  PIN की ज़रूरत नहीं।",
  "Channels filled in": "भरे गए चैनल",
  "Channels freeze, no guide, no sound, TiviBro closed or is slow: what to try first.": "चैनल अटकते हैं, गाइड नहीं दिखता, आवाज़ नहीं आती, TiviBro बंद हो जाता है या धीमा है: पहले क्या आज़माएं.",
  "Channels from groups you hid still appear in All channels.": "जिन ग्रुप को आपने छिपाया है, उनके चैनल अब भी सभी चैनल में दिखते हैं.",
