  "Channels named \"Off Air\", \"Offline\" or \"No Event Scheduled\", empty slots like \"PPV 09 |\", and events that ended hours ago stay out of the lists until the provider names a new event on them.  Favorites keep theirs.": "\"Off Air\", \"Offline\" या \"No Event Scheduled\" नाम वाले चैनल, \"PPV 09 |\" जैसे खाली स्लॉट और घंटों पहले खत्म हो चुके इवेंट सूचियों में तब तक नहीं आते, जब तक प्रोवाइडर उन पर नया इवेंट नहीं देता.  पसंदीदा में ये बने रहते हैं.",
