  "Cleaned up: each channel's own logo, trimmed, in white where it needs it for dark screens (Worldwide TV Logos).  In colour: the same logos in their own colours.  Matching set: one style (tv-logos).  Original: as iptv-org has it.": "साफ़ किया हुआ: हर चैनल का अपना लोगो, कटा-छँटा, जहाँ गहरी स्क्रीन पर ज़रूरत हो वहाँ सफ़ेद (Worldwide TV Logos)।  रंगीन: वही लोगो अपने रंगों में।  मैचिंग सेट: एक स्टाइल (tv-logos)।  ओरिजिनल: जैसा iptv-org में है।",
