  "Each library is one folder on a media server (DLNA / UPnP, a Windows share, WebDAV, Dropbox or Google Drive) holding movies or TV shows, like Plex's libraries.  Select one to scan it, fix what didn't match, choose whether it shows on Home, or remove it.": "हर लाइब्रेरी मीडिया सर्वर (DLNA / UPnP, Windows शेयर, WebDAV, Dropbox या Google Drive) का एक फ़ोल्डर होती है, जिसमें फ़िल्में या TV शो होते हैं, ठीक Plex की लाइब्रेरी की तरह।  किसी एक को चुनकर स्कैन करें, जो मैच नहीं हुआ उसे ठीक करें, तय करें कि वह होम पर दिखे या नहीं, या उसे हटाएं।",
  "Each playlist keeps its own groups, favorites, hidden items, guide and name rules.  Adding one from the phone app is easier: share your provider's link to it.": "हर प्लेलिस्ट के अपने ग्रुप, पसंदीदा, छिपे हुए आइटम, गाइड और नाम के नियम होते हैं।  फ़ोन ऐप से जोड़ना आसान है: अपने प्रोवाइडर का लिंक उसमें शेयर करें।",
