  "Even width": "समान चौड़ाई",
  "Even width lines up channel numbers and times and keeps the buffer info steady.  Fixed width also crosses the zero.": "समान चौड़ाई चैनल नंबर और समय को एक सीध में रखती है और बफ़र की जानकारी को स्थिर रखती है.  फ़िक्स्ड चौड़ाई में शून्य पर आड़ी लकीर भी होती है.",
  "Event channels": "इवेंट चैनल",
  "Events by time": "समय के अनुसार इवेंट",
  "Events by time is off": "समय के अनुसार इवेंट बंद है",
  "Every 15 minutes": "हर 15 मिनट में",
  "Every 6 hours": "हर 6 घंटे में",
  "Every channel uses the setting above": "हर चैनल ऊपर की सेटिंग इस्तेमाल करता है",
  "Every colour at once.  Your own mix: pick an accent and a background.": "सारे रंग एक साथ।  अपना मिक्स: एक एक्सेंट और एक बैकग्राउंड चुनें।",
  "Every colour at once: Black and white, Tokyo Night, Dracula, Nord, Gruvbox and more.  Your own mix: choose a background and an accent below.": "सारे रंग एक साथ: Black and white, Tokyo Night, Dracula, Nord, Gruvbox और भी बहुत कुछ।  अपना मिक्स: नीचे एक बैकग्राउंड और एक एक्सेंट चुनें।",
  "Every hour": "हर घंटे",
  "Every language": "हर भाषा",
  "Every movie here has been looked up.": "यहाँ हर फ़िल्म की जानकारी खोज ली गई है।",
  "Every request the helper made: status, time, size, and the network error if any.": "हेल्पर का किया हर रिक्वेस्ट: स्टेटस, समय, साइज़ और नेटवर्क एरर, अगर कोई हो।",
