  "Extras": "एक्स्ट्रा",
  "FFmpeg is unmodified, built from ffmpeg.org/releases/ffmpeg-7.1.1.tar.xz by scripts/ffmpeg/build.sh in TiviBro's repository.  It runs as a separate program, which you can replace with your own build.": "FFmpeg में कोई बदलाव नहीं किया गया है। इसे TiviBro की रिपॉज़िटरी में scripts/ffmpeg/build.sh से ffmpeg.org/releases/ffmpeg-7.1.1.tar.xz से बनाया गया है।  यह एक अलग प्रोग्राम के रूप में चलता है, जिसे आप अपने बनाए बिल्ड से बदल सकते हैं।",
  "Fallback audio language": "वैकल्पिक ऑडियो भाषा",
  "Fast forward": "फ़ास्ट फ़ॉरवर्ड",
