  "Favorite movies": "पसंदीदा फ़िल्में",
  "Favorite shows": "पसंदीदा शो",
  "Favorite, details, episode order and more": "पसंदीदा, जानकारी, एपिसोड का क्रम और बहुत कुछ",
  "Favorites also in lists": "पसंदीदा सूचियों में भी",
  "Favorites and your groups above the provider groups.": "पसंदीदा और आपके ग्रुप प्रोवाइडर के ग्रुप से ऊपर।",
  "Fetch details for all": "सभी की जानकारी लाएं",
  "Fetch missing details": "बाकी जानकारी लाएं",
  "Fetch movie details from TMDB?  Titles and years or saved movie IDs are sent to TMDB.  Images load from image.tmdb.org.  Your source logins are never sent.": "TMDB से फ़िल्मों की जानकारी लाएं?  टाइटल और साल या सेव की गई फ़िल्म ID TMDB को भेजी जाती हैं।  इमेज image.tmdb.org से लोड होती हैं।  आपके सोर्स के login कभी नहीं भेजे जाते।",
  "Fetch movie details from TheTVDB?  Titles and years or saved movie IDs are sent to TheTVDB through TiviBro's service.  Images load from artworks.thetvdb.com.  Your source logins are never sent.": "TheTVDB से फ़िल्मों की जानकारी लाएं?  टाइटल और साल या सेव की गई फ़िल्म ID TiviBro की सर्विस के ज़रिए TheTVDB को भेजी जाती हैं।  इमेज artworks.thetvdb.com से लोड होती हैं।  आपके सोर्स के login कभी नहीं भेजे जाते।",
  "Fetch show details from TMDB?  Show names and years or saved show IDs are sent to TMDB.  Images load from image.tmdb.org.  Your source logins are never sent.": "TMDB से शो की जानकारी लाएं?  शो के नाम और साल या सेव की गई शो ID TMDB को भेजी जाती हैं।  इमेज image.tmdb.org से लोड होती हैं।  आपके सोर्स के login कभी नहीं भेजे जाते।",
  "Fetch show details from TheTVDB?  Show names and years or saved show IDs are sent to TheTVDB through TiviBro's service.  Images load from artworks.thetvdb.com.  Your source logins are never sent.": "TheTVDB से शो की जानकारी लाएं?  शो के नाम और साल या सेव की गई शो ID TiviBro की सर्विस के ज़रिए TheTVDB को भेजी जाती हैं।  इमेज artworks.thetvdb.com से लोड होती हैं।  आपके सोर्स के login कभी नहीं भेजे जाते।",
  "Fetching TV show details…": "TV शो की जानकारी लाई जा रही है…",
  "Fetching details for {x} on the TV.": "TV पर {x} की जानकारी लाई जा रही है।",
  "Fetching details now": "जानकारी अभी लाई जा रही है",
  "File information": "फ़ाइल की जानकारी",
  "Files TiviBro could not place.  OK to sort them out.": "वे फ़ाइलें जिन्हें TiviBro कहीं रख नहीं पाया।  उन्हें छाँटने के लिए OK दबाएं।",
  "Filipino": "फ़िलिपीनो",
