  "Hide {x}": "{x} छिपाएं",
  "Hides every channel and group with it in the name, as a whole word: \"WXYZ\", \"Shopping\".": "जिस चैनल और ग्रुप के नाम में यह पूरा शब्द हो, उसे छिपा देता है: \"WXYZ\", \"Shopping\".",
  "Hides the last picture until the next channel starts.": "अगला चैनल शुरू होने तक आख़िरी तस्वीर छिपा देता है.",
  "Hides what the summary says, after saving a restore point.": "रिस्टोर पॉइंट सेव करने के बाद, सारांश में बताई चीज़ें छिपा देता है.",
  "High": "हाई",
  "Higher keeps the lines clear of a picture's own captions or a score bar.  For subtitles TiviBro draws (most of them); the TV's own keep their place.  Also in the player: Subtitles > Size and style.": "ऊपर रखने से लाइनें तस्वीर के अपने कैप्शन या स्कोर बार से दूर रहती हैं.  यह TiviBro के बनाए सबटाइटल के लिए है (ज़्यादातर); TV के अपने सबटाइटल अपनी जगह रहते हैं.  प्लेयर में भी: सबटाइटल > साइज़ और स्टाइल.",
  "Highly rated you haven't seen": "ऊँची रेटिंग वाले, जो आपने नहीं देखे",
  "Hindi": "हिन्दी",
  "Hold OK  channel options": "OK दबाए रखें  चैनल विकल्प",
