  "In time, then early or late, then in time again: that subtitle was made for another cut of the film.  Try another download.": "पहले सही समय पर, फिर आगे या पीछे, फिर दोबारा सही समय पर: यह सबटाइटल फ़िल्म के किसी दूसरे वर्शन के लिए बना है।  कोई दूसरा डाउनलोड आज़माएं।",
