  "It needs a Google Cloud service account that the drive or folder is shared with.  The web editor walks you through it.": "इसके लिए एक Google Cloud सर्विस अकाउंट चाहिए, जिसके साथ ड्राइव या फ़ोल्डर शेयर किया गया हो।  वेब एडिटर आपको पूरा तरीका बताता है।",
