  "Its Recently added, Continue watching and favorites on My media's Home.  Off: only on the Movies and TV shows tabs.": "इसके हाल में जोड़े गए, देखना जारी रखें और पसंदीदा मेरा मीडिया के होम पर दिखेंगे।  बंद: सिर्फ़ फ़िल्में और TV शो टैब में।",
  "Its folder, Dropbox sign-in, pause or restart a scan.  On the phone: its own form.": "इसका फ़ोल्डर, Dropbox साइन-इन, स्कैन रोकना या दोबारा शुरू करना।  फ़ोन पर: इसका अपना फ़ॉर्म।",
