  "Keeps every city again.": "हर शहर फिर से रखता है.",
  "Keeps paused TV on the share chosen for recordings, up to 2 hours.  Off: the TV's own storage, 10 minutes.": "रुके हुए TV को रिकॉर्डिंग के लिए चुने गए शेयर पर रखता है, 2 घंटे तक.  बंद: TV की अपनी स्टोरेज, 10 मिनट.",
  "Keeps the channel you watch fullscreen on the USB drive or network share the whole time, so ◀ goes back to something you just missed without pausing first (like a DVR).  Channels start a second or two slower, and the drive or share is written all the time.  Needs Pause live TV on, and a USB drive or a network share.": "फ़ुलस्क्रीन में देखा जा रहा चैनल पूरे समय USB ड्राइव या नेटवर्क शेयर पर रखता है, ताकि बिना पहले रोके ◀ दबाकर अभी छूटा हुआ हिस्सा देख सकें (DVR की तरह).  चैनल शुरू होने में एक-दो सेकंड ज़्यादा लगते हैं, और ड्राइव या शेयर पर हर समय लिखा जाता है.  लाइव पॉज़ चालू होना ज़रूरी है, और USB ड्राइव या नेटवर्क शेयर भी.",
