  "Like Radarr and Sonarr: a trakt.tv/users/NAME/lists/LIST link, or NAME/LIST.  The list must be public, or yours.": "Radarr और Sonarr की तरह: trakt.tv/users/NAME/lists/LIST लिंक, या NAME/LIST.  लिस्ट पब्लिक होनी चाहिए, या आपकी अपनी.",
  "Like the watchlist: how far ahead it looks, and a reminder or just a message, are set in Settings > Reminders and watchlist > Watchlist.": "वॉचलिस्ट की तरह: यह कितना आगे तक देखती है, और रिमाइंडर या सिर्फ़ संदेश, सेटिंग > रिमाइंडर और वॉचलिस्ट > वॉचलिस्ट में सेट होते हैं.",
