  "Live TV in fullscreen, when the channel sends them (most US channels do).  Also in the quick menu (OK in fullscreen), for every channel at once.  Not with the TV player.": "फ़ुलस्क्रीन लाइव TV में, जब चैनल उन्हें भेजता है (अमेरिका के ज़्यादातर चैनल भेजते हैं)।  क्विक मेनू में भी (फ़ुलस्क्रीन में OK), सभी चैनलों के लिए एक साथ।  TV प्लेयर के साथ नहीं।",
