  "Logos from three open projects, Worldwide TV Logos, tv-logos and iptv-org, matched to your channels by guide id, name and country.  Fill in missing logos only changes channels with no logo of their own (or one that doesn't load).  Use for every channel it knows gives them all the library's style.  TiviBro hosts no images: each logo loads from its project.": "तीन ओपन प्रोजेक्ट, Worldwide TV Logos, tv-logos और iptv-org, के लोगो, जो गाइड id, नाम और देश के हिसाब से आपके चैनलों से मिलाए जाते हैं।  छूटे लोगो भरें सिर्फ़ उन चैनलों को बदलता है जिनका अपना लोगो नहीं है (या लोड नहीं होता)।  पहचाने हुए हर चैनल के लिए इस्तेमाल करें सभी को लाइब्रेरी का स्टाइल दे देता है।  TiviBro कोई इमेज होस्ट नहीं करता: हर लोगो अपने प्रोजेक्ट से लोड होता है।",
  "Logs out every browser.": "हर ब्राउज़र से लॉग आउट कर देता है।",
