  "Loud scenes brought down and quiet talk brought up, for watching with the volume low.  Works with or without dialogue boost.": "तेज़ आवाज़ वाले सीन धीमे और धीमी बातचीत तेज़ होती है, कम वॉल्यूम पर देखने के लिए।  डायलॉग बूस्ट के साथ या उसके बिना, दोनों में काम करता है।",
