  "Movies TMDB hasn't been asked about yet (a lookup that stopped, or no token then).  OK looks them up now; it also happens by itself.": "वे फ़िल्में जिनके बारे में TMDB से अभी पूछा नहीं गया (खोज बीच में रुक गई, या तब टोकन नहीं था).  OK दबाने पर अभी खोजी जाती हैं; यह अपने आप भी होता है.",
  "Movies and Shows open on": "फ़िल्में और शो इस पर खुलते हैं",
