  "Movies or TV shows decides how files are read and which tab they go to.  Movies and TV shows sorts each file by its name.": "फ़िल्में या TV शो तय करता है कि फ़ाइलें कैसे पढ़ी जाएं और किस टैब में जाएं.  फ़िल्में और TV शो हर फ़ाइल को उसके नाम से छांटता है.",
  "Movies or TV shows from a DLNA / UPnP server, a Windows or network share (name and login), a WebDAV folder (address and login), Dropbox (signs in from the phone app) or Google Drive (the web editor or the phone app).  Subfolders are scanned too.": "DLNA / UPnP सर्वर, Windows या नेटवर्क शेयर (नाम और लॉगिन), WebDAV फ़ोल्डर (पता और लॉगिन), Dropbox (फ़ोन ऐप से साइन इन होता है) या Google Drive (वेब एडिटर या फ़ोन ऐप) की फ़िल्में या TV शो.  सबफ़ोल्डर भी स्कैन होते हैं.",
  "Movies you left out of My media by hand.  Include one back from here.": "वे फ़िल्में जिन्हें आपने मेरा मीडिया से हाथ से बाहर रखा.  यहां से किसी को वापस जोड़ें.",
