  "Names that say ET, PT or UK are read that way.  This is for the rest.  Shown in this TV's own time.": "जिन नामों में ET, PT या UK लिखा है, उन्हें उसी तरह पढ़ा जाता है।  यह बाकी सबके लिए है।  इस TV के अपने समय में दिखता है।",
