  "OK to type a name": "नाम लिखने के लिए OK",
  "OK turns a button on or off.  Hold OK on one to move it.  Buttons only appear when they apply: Audio needs two or more tracks, Record a USB drive or share.": "OK से बटन चालू या बंद होता है.  बटन को ले जाने के लिए उस पर OK दबाए रखें.  बटन तभी दिखते हैं जब वे लागू हों: ऑडियो के लिए दो या ज़्यादा ट्रैक, रिकॉर्ड करें के लिए USB ड्राइव या शेयर चाहिए.",
  "Off": "बंद",
  "Off asks for the PIN every time.": "बंद होने पर हर बार PIN पूछा जाता है।",
  "Off keeps the list here without its shelf.": "बंद होने पर लिस्ट यहीं रहती है, उसकी शेल्फ़ के बिना।",
  "Off or unreachable": "बंद है या पहुँच से बाहर",
  "Off shows just the number and name.": "बंद होने पर सिर्फ़ नंबर और नाम दिखते हैं।",
  "Off shows logos only, leaving more room.": "बंद होने पर सिर्फ़ लोगो दिखते हैं, जिससे ज़्यादा जगह मिलती है।",
  "Off, HDR10": "बंद, HDR10",
  "On": "चालू",
  "On My media": "मेरा मीडिया पर",
  "On Trakt": "Trakt पर",
  "On a network share, a recording can be watched once its first 10 minutes are up there.  Yellow goes to the channel live.": "नेटवर्क शेयर पर रिकॉर्डिंग के पहले 10 मिनट वहाँ पहुँचते ही उसे देखा जा सकता है।  Yellow दबाने पर चैनल लाइव चलता है।",
  "On now": "अभी चल रहा है",
  "On now, score hidden": "अभी चल रहा है, स्कोर छिपा है",
  "On shelves that mix categories (Recently added, Continue watching, My list, TMDB's lists), each poster says which category it's in, after its year and rating.  Long names are cut short.": "जिन शेल्फ़ में अलग-अलग कैटेगरी मिली होती हैं (हाल ही में जोड़े गए, देखना जारी रखें, मेरी लिस्ट, TMDB की लिस्ट), वहाँ हर पोस्टर साल और रेटिंग के बाद बताता है कि वह किस कैटेगरी में है।  लंबे नाम छोटे कर दिए जाते हैं।",
  "On the Channels screen": "चैनल स्क्रीन पर",
  "On the USB drive, in \"TiviBro Recordings\"": "USB ड्राइव पर, \"TiviBro Recordings\" में",
  "On the drive: {x}": "ड्राइव पर: {x}",
  "On time": "समय पर",
  "On your channels": "आपके चैनलों पर",
  "On your network": "आपके नेटवर्क पर",
  "On your phone or computer, open opensubtitles.com": "अपने फ़ोन या कंप्यूटर पर opensubtitles.com खोलें",
  "On {x}": "{x} पर",
  "On {x} and {n} more": ["{x} पर और {n} और", "{x} पर और {n} और"],
  "On, 4K too": "चालू, 4K भी",
  "On, none here": "चालू, यहाँ कोई नहीं",
  "On: a favorite movie or show is in Favorites and also in Movies or TV shows.  Off: only in Favorites.": "चालू: पसंदीदा फ़िल्म या शो पसंदीदा में भी दिखता है और फ़िल्में या TV शो में भी।  बंद: सिर्फ़ पसंदीदा में।",
  "On: the full guide was {x} {y}, and is corrected.": "चालू: पूरा गाइड {x} {y} था, और अब ठीक कर दिया गया है।",
  "Once a day, and when a new version first starts, TiviBro says which version it is (and whether it is new or an update) and which webOS this TV has.  The count also notes the country it came from, to see which languages to add next.  Nothing else: no address is kept, no ID, nothing about your channels or playlists.": "दिन में एक बार, और जब कोई नया वर्शन पहली बार शुरू होता है, TiviBro बताता है कि वह कौन सा वर्शन है (और नया इंस्टॉल है या अपडेट) और इस TV में कौन सा webOS है।  गिनती में यह भी दर्ज होता है कि वह किस देश से आई, ताकि पता चले कि आगे कौन सी भाषाएँ जोड़नी हैं।  और कुछ नहीं: कोई पता नहीं रखा जाता, कोई ID नहीं, आपके चैनल या प्लेलिस्ट के बारे में कुछ भी नहीं।",
  "One group with your stations, by city and network.": "आपके स्टेशनों का एक ग्रुप, शहर और नेटवर्क के हिसाब से।",
  "One moment…": "एक पल…",
  "One movie after another, in order": "एक के बाद एक फ़िल्म, क्रम से",
  "One or two addresses, IPv4 or IPv6 (192.168.1.1, 2001:de4::101), or a DNS-over-HTTPS link (https://dns.example/dns-query).": "एक या दो पते, IPv4 या IPv6 (192.168.1.1, 2001:de4::101), या DNS-over-HTTPS लिंक (https://dns.example/dns-query)।",
  "Online": "ऑनलाइन",
  "Only for channels with no other guide.": "सिर्फ़ उन चैनलों के लिए जिनका कोई और गाइड नहीं है।",
  "Only if your provider asks for a specific one.  Sent by the network helper for this playlist.": "सिर्फ़ तब जब आपका प्रोवाइडर कोई खास माँगे।  इस प्लेलिस्ट के लिए नेटवर्क हेल्पर इसे भेजता है।",
  "Only phones you pair here can connect.  The pairing code never crosses the network, and everything a phone sends is signed with a key only that phone and this TV have.": "सिर्फ़ वही फ़ोन कनेक्ट हो सकते हैं जिन्हें आप यहाँ पेयर करते हैं।  पेयरिंग कोड कभी नेटवर्क पर नहीं जाता, और फ़ोन जो कुछ भेजता है वह एक ऐसी की से साइन होता है जो सिर्फ़ उस फ़ोन और इस TV के पास है।",
  "Only some parts out of time?": "सिर्फ़ कुछ हिस्से आगे-पीछे हैं?",
  "Only when I press Green": "सिर्फ़ जब मैं Green दबाऊँ",
  "Only your own lists will apply.": "सिर्फ़ आपकी अपनी लिस्ट लागू होंगी।",
  "Open": "खोलें",
