  "Or hold OK on any channel and choose Assign guide.  A channel that will never have a guide: hold OK > No guide for this channel.": "या किसी भी चैनल पर OK को दबाए रखें और गाइड असाइन करें चुनें।  जिस चैनल का गाइड कभी नहीं होगा: OK दबाए रखें > इस चैनल के लिए गाइड नहीं।",
