  "Other showings…": "अन्य प्रसारण…",
  "Other sites answer, so the TV's internet works: this is on your provider's side.": "दूसरी साइटें खुल रही हैं, यानी TV का इंटरनेट चल रहा है: समस्या आपके प्रोवाइडर की तरफ़ है।",
  "Other sites haven't been checked yet: Check now looks.": "दूसरी साइटें अभी जांची नहीं गई हैं: अभी जांचें दबाएं।",
  "Other versions": "अन्य वर्शन",
