  "Other versions…": "अन्य वर्शन…",
  "Outline": "आउटलाइन",
  "Outline keeps the picture clear; a box is easier to read over bright scenes.": "आउटलाइन से तस्वीर साफ़ रहती है; चमकीले दृश्यों पर बॉक्स पढ़ना आसान होता है।",
  "Over 2 and a half hours  ·": "ढाई घंटे से ज़्यादा  ·",
