  "Paired with {x}.  You can close this screen.": "{x} से पेयर हो गया।  आप यह स्क्रीन बंद कर सकते हैं।",
  "Pairing code": "पेयरिंग कोड",
  "Pairing the TiviBro app is different: Settings > Phone app and web editor > Pair the TiviBro app.": "TiviBro ऐप पेयर करने का तरीका अलग है: सेटिंग > फ़ोन ऐप और वेब एडिटर > TiviBro ऐप पेयर करें।",
  "Panels over video": "वीडियो के ऊपर पैनल",
