  "Password": "पासवर्ड",
  "Password for": "पासवर्ड:",
  "Paste a comma separated list…": "कॉमा से अलग की गई सूची पेस्ट करें…",
  "Paste a list's link": "सूची का लिंक पेस्ट करें",
  "Paste these from the TiviBro phone app (Settings > API keys): a phone keyboard and copy and paste make it quick.": "इन्हें TiviBro फ़ोन ऐप (सेटिंग > API keys) से पेस्ट करें: फ़ोन के कीबोर्ड और कॉपी-पेस्ट से यह जल्दी हो जाता है।",
  "Pastel": "पेस्टल",
  "Pause and rewind": "पॉज़ और रिवाइंड",
  "Pause keeps the channel, and Play carries on from where you paused, with ◀ ▶ to go back and forth in it.  On a USB drive (a rooted TV) or a network share it keeps up to 2 hours; without either, up to 10 minutes in the TV's own storage.  Off: pause holds for as long as the player's buffer, then Play is live.": "पॉज़ करने पर चैनल रुक जाता है, और प्ले दबाने पर वहीं से चलता है जहाँ आपने पॉज़ किया था, ◀ ▶ से आगे-पीछे जा सकते हैं।  USB ड्राइव (रूटेड TV) या नेटवर्क शेयर पर यह 2 घंटे तक रखता है; दोनों न हों तो TV की अपनी स्टोरेज में 10 मिनट तक।  बंद: पॉज़ सिर्फ़ प्लेयर के बफ़र जितनी देर रुकता है, फिर प्ले करने पर लाइव चलता है।",
  "Pause live TV": "लाइव TV पॉज़ करें",
  "Pause scan": "स्कैन रोकें",
  "Paused": "पॉज़ किया गया",
  "Pay-per-view and league pass channels whose names carry the game and its time: read into the guide.": "पे-पर-व्यू और लीग पास चैनल, जिनके नाम में मैच और उसका समय होता है: इन्हें गाइड में पढ़ लिया जाता है।",
  "Phone app and web editor": "फ़ोन ऐप और वेब एडिटर",
  "Phone app connection": "फ़ोन ऐप कनेक्शन",
  "Pick a channel": "कोई चैनल चुनें",
  "Pick a group that isn't ticked; the ticked ones go into it.": "ऐसा ग्रुप चुनें जिस पर टिक नहीं है; टिक किए हुए उसी में चले जाएंगे।",
  "Pick a release to go back to.  It's checked like an update (its fingerprint and TiviBro's signature) and installed through the Homebrew Channel.  Before that, everything TiviBro keeps on this TV (settings, channel edits, favorites, reminders) is saved, and a restore point is made.  Recordings, your playlist and My media stay as they are.  Automatic update checks turn off, so the newer version isn't offered straight back.": "वापस जाने के लिए कोई रिलीज़ चुनें।  इसे अपडेट की तरह जांचा जाता है (इसका फ़िंगरप्रिंट और TiviBro का सिग्नेचर) और Homebrew Channel से इंस्टॉल किया जाता है।  इससे पहले, TiviBro इस TV पर जो कुछ रखता है (सेटिंग, चैनल में बदलाव, पसंदीदा, रिमाइंडर) वह सेव हो जाता है, और एक रिस्टोर पॉइंट बन जाता है।  रिकॉर्डिंग, आपकी प्लेलिस्ट और मेरा मीडिया जैसे हैं वैसे ही रहते हैं।  ऑटोमैटिक अपडेट जांच बंद हो जाती है, ताकि नया वर्शन तुरंत दोबारा न दिखे।",
  "Pick a share first.": "पहले कोई शेयर चुनें।",
  "Pick of the day": "आज की पसंद",
  "Pick the other version": "दूसरा वर्शन चुनें",
  "Pick which ticked group the others go into.": "चुनें कि बाकी टिक किए गए ग्रुप किस ग्रुप में जाएं।",
  "Picks the 5.1 or Dolby track when there is one in that language.  Your soundbar or TV needs to support it.": "उस भाषा में 5.1 या Dolby ट्रैक हो तो वही चुनता है।  आपके साउंडबार या TV में इसका सपोर्ट होना चाहिए।",
