  "Plays the channel you rest on.  Turn off on very slow TVs for the snappiest list.": "जिस चैनल पर आप रुकते हैं, उसे चलाता है।  बहुत धीमे TV पर इसे बंद कर दें, ताकि लिस्ट सबसे तेज़ चले।",
