  "Posters, details, episodes, trailers and skip times for shows: in the guide, your provider's Shows, My media and Up next.  TMDB needs your token.  TheTVDB needs nothing: it comes through TiviBro's own service, and only titles leave the TV.  Metadata provided by TheTVDB (thetvdb.com).": "शो के पोस्टर, जानकारी, एपिसोड, ट्रेलर और छोड़ने के समय: गाइड में, आपके प्रोवाइडर के शो, मेरा मीडिया और अब अगला में।  TMDB के लिए आपका टोकन चाहिए।  TheTVDB को कुछ नहीं चाहिए: यह TiviBro की अपनी सेवा से आता है, और TV से सिर्फ़ टाइटल बाहर जाते हैं।  मेटाडेटा TheTVDB (thetvdb.com) द्वारा उपलब्ध कराया गया।",
  "Posters, details, trailers and skip times for movies: in the guide (Movies on now), your provider's Movies and My media.  TMDB needs your token.  TheTVDB needs nothing: it comes through TiviBro's own service, and only titles leave the TV.  Metadata provided by TheTVDB (thetvdb.com).": "फ़िल्मों के पोस्टर, जानकारी, ट्रेलर और छोड़ने के समय: गाइड में (अभी चल रही फ़िल्में), आपके प्रोवाइडर की फ़िल्में और मेरा मीडिया में।  TMDB के लिए आपका टोकन चाहिए।  TheTVDB को कुछ नहीं चाहिए: यह TiviBro की अपनी सेवा से आता है, और TV से सिर्फ़ टाइटल बाहर जाते हैं।  मेटाडेटा TheTVDB (thetvdb.com) द्वारा उपलब्ध कराया गया।",
