  "Reachable, but this TV can only unzip .gz guides through the network helper.  Set Settings > Playback > Connection to Automatic, or use the plain .xml address.": "पहुँच में है, लेकिन यह TV .gz गाइड सिर्फ़ नेटवर्क हेल्पर के ज़रिए अनज़िप कर सकता है.  सेटिंग > प्लेबैक > कनेक्शन को ऑटोमैटिक करें, या सीधा .xml पता इस्तेमाल करें.",
