  "Record to": "रिकॉर्ड करने की जगह",
  "Record to a USB drive on a rooted TV, or to a network share on any TV.  webOS keeps USB drives from apps installed in developer mode; on a rooted TV (the Homebrew Channel) TiviBro's helper reaches them.  A network share works without root: a Windows or Samba share (a PC, Mac, NAS or router) or WebDAV (Synology, QNAP, TrueNAS, Unraid, Nextcloud).  Add it as a library in My media, then choose it below.  Live pause then goes there too, for hours.  Without either, live pause keeps up to 10 minutes in the TV's own storage.": "रूट किए गए TV पर USB ड्राइव में रिकॉर्ड करें, या किसी भी TV पर नेटवर्क शेयर में।  webOS डेवलपर मोड में इंस्टॉल किए गए ऐप्स को USB ड्राइव तक पहुँचने नहीं देता; रूट किए गए TV (Homebrew Channel) पर TiviBro का हेल्पर उन तक पहुँच जाता है।  नेटवर्क शेयर बिना रूट के काम करता है: Windows या Samba शेयर (PC, Mac, NAS या राउटर) या WebDAV (Synology, QNAP, TrueNAS, Unraid, Nextcloud)।  इसे मेरा मीडिया में लाइब्रेरी की तरह जोड़ें, फिर नीचे उसे चुनें।  तब लाइव पॉज़ भी वहीं चलेगा, कई घंटों तक।  दोनों में से कुछ न हो तो लाइव पॉज़ TV की अपनी स्टोरेज में ज़्यादा से ज़्यादा 10 मिनट रखता है।",
  "Record to a share on your network (a PC, Mac or NAS): no USB drive or root needed.  Choose one of your My media libraries on a Windows share or WebDAV.  Live pause goes there too.": "अपने नेटवर्क के शेयर (PC, Mac या NAS) में रिकॉर्ड करें: USB ड्राइव या रूट की ज़रूरत नहीं।  मेरा मीडिया में Windows शेयर या WebDAV वाली अपनी लाइब्रेरी में से एक चुनें।  लाइव पॉज़ भी वहीं चलेगा।",
