  "Scan a QR code: your phone fills in a GitHub issue with this TV's details and log, logins and server names taken out.  In the phone app it opens the report page there.": "QR कोड स्कैन करें: आपका फ़ोन इस TV की जानकारी और लॉग के साथ GitHub इश्यू भर देता है, लॉगिन और सर्वर के नाम हटाकर।  फ़ोन ऐप में यह वहीं रिपोर्ट पेज खोलता है।",
  "Scan a code with your phone: Smart clean-up, renaming, sorting and backups with a real keyboard.": "फ़ोन से कोड स्कैन करें: असली कीबोर्ड से स्मार्ट क्लीन-अप, नाम बदलना, सॉर्ट करना और बैकअप।",
