  "Scan saved.  Continuing": "स्कैन सेव हो गया।  जारी है",
  "Scan the code with your phone's camera (or open the address on a computer).  Describe what happened there; the TV adds its version, model and log, with logins and server names taken out, and your phone opens a GitHub issue ready to send.": "कोड को फ़ोन के कैमरे से स्कैन करें (या कंप्यूटर पर यह पता खोलें)।  वहाँ बताएं कि क्या हुआ; TV अपना वर्शन, मॉडल और लॉग जोड़ देता है, लॉगिन और सर्वर के नाम हटाकर, और आपका फ़ोन भेजने के लिए तैयार GitHub इश्यू खोल देता है।",
  "Scan the code with your phone's camera, or open the address on a computer on the same network.  Rename, hide, sort and clean up with a real keyboard; changes show up here as you send them.": "कोड को फ़ोन के कैमरे से स्कैन करें, या उसी नेटवर्क के कंप्यूटर पर यह पता खोलें।  असली कीबोर्ड से नाम बदलें, छिपाएं, सॉर्ट और क्लीन-अप करें; आप जैसे भेजेंगे, बदलाव यहाँ दिखते जाएंगे।",
  "Scan will pause after the current request.": "मौजूदा रिक्वेस्ट के बाद स्कैन रुक जाएगा।",
