  "Shows a code for a computer or phone browser: the web editor's My media page, for typing server logins, fixing many matches at once and TV show episodes.": "कंप्यूटर या फ़ोन ब्राउज़र के लिए कोड दिखाता है: वेब एडिटर का मेरा मीडिया पेज, जहाँ सर्वर लॉगिन डालें, कई मैच एक साथ ठीक करें और TV शो के एपिसोड देखें.",
  "Shows a code to enter at plex.tv/link on your phone or computer.  No password is typed on the TV.": "एक कोड दिखाता है, जिसे अपने फ़ोन या कंप्यूटर पर plex.tv/link पर डालें.  TV पर कोई पासवर्ड टाइप नहीं करना पड़ता.",
  "Shows a code to enter at trakt.tv/activate on your phone or computer.  No password is typed on the TV.": "एक कोड दिखाता है, जिसे अपने फ़ोन या कंप्यूटर पर trakt.tv/activate पर डालें.  TV पर कोई पासवर्ड टाइप नहीं करना पड़ता.",
  "Shows each programme's time under its title in the grid.": "ग्रिड में हर कार्यक्रम के शीर्षक के नीचे उसका समय दिखाता है.",
  "Shows how many seconds of video are banked, in fullscreen.": "फ़ुलस्क्रीन में दिखाता है कि कितने सेकंड का वीडियो जमा है.",
  "Shows that need review": "जिन शो की समीक्षा ज़रूरी है",
  "Shows the QR code and the code to scan in the TiviBro app (not the phone's camera).": "QR कोड और TiviBro ऐप में स्कैन करने का कोड दिखाता है (फ़ोन के कैमरे से नहीं).",
  "Shows what the app sees when you press a button.  The TV's own buttons (Home, Live TV, Guide, Input) never reach TiviBro.": "बटन दबाने पर ऐप को क्या दिखता है, यह दिखाता है.  TV के अपने बटन (होम, लाइव TV, गाइड, इनपुट) TiviBro तक कभी नहीं पहुँचते.",
