  "That isn't a server name or address.  Try its name (like NAS or DESKTOP-PC) or its IP address.": "यह सर्वर का नाम या पता नहीं है।  उसका नाम (जैसे NAS या DESKTOP-PC) या IP एड्रेस डालकर देखें।",
