  "The TV plays the file itself when it can, at full quality, with the server doing nothing.  Off: the server always converts it (for a file that stutters).": "जब हो सके, TV फ़ाइल खुद चलाता है, पूरी क्वालिटी में, और सर्वर कुछ नहीं करता.  बंद: सर्वर हमेशा उसे कन्वर्ट करता है (अटकने वाली फ़ाइल के लिए)।",
