  "The TV's storage for TiviBro is full, so recent changes could not be saved.  Try clearing old reminders or watch history.": "TiviBro के लिए TV की स्टोरेज भर गई है, इसलिए हाल के बदलाव सेव नहीं हो सके।  पुराने रिमाइंडर या देखने का इतिहास हटाकर देखें।",
