  "The group of event channels on now or starting in the next two weeks, soonest first.  The same switch as in Event channels.": "इवेंट चैनलों का ग्रुप जो अभी चल रहे हैं या अगले दो हफ़्तों में शुरू होंगे, जो सबसे पहले हैं वे ऊपर.  यह वही स्विच है जो इवेंट चैनल में है.",
