  "The guide is still loading.  Try again when it has finished, so channels it fills in stay shown.": "गाइड अभी लोड हो रहा है.  लोड पूरा होने पर फिर कोशिश करें, ताकि गाइड से भरे गए चैनल दिखते रहें.",
  "The guide shows the event at its time, with \"Starts 7:30 PM\" before it.  A real guide always wins.": "गाइड इवेंट को उसके समय पर दिखाता है, उससे पहले \"शुरू 7:30 PM\" के साथ.  असली गाइड को हमेशा प्राथमिकता मिलती है.",
