  "Top 10": "टॉप 10",
  "Top 10 data from FlixPatrol (flixpatrol.com), used with their permission.": "टॉप 10 डेटा FlixPatrol (flixpatrol.com) से, उनकी अनुमति से इस्तेमाल किया गया.",
  "Top 10 movies on {x}": "{x} पर टॉप 10 फ़िल्में",
