  "US sports networks (Big Ten, SEC, ACC, ESPN, FS1, regional sports networks) and team channels, from EPGTalk and epgshare01.  They also stand in for a sports channel's own guide when theirs reaches further ahead.  Needs the helper.": "US स्पोर्ट्स नेटवर्क (Big Ten, SEC, ACC, ESPN, FS1, रीजनल स्पोर्ट्स नेटवर्क) और टीम चैनल, EPGTalk और epgshare01 से।  जब इनका गाइड स्पोर्ट्स चैनल के अपने गाइड से ज़्यादा आगे तक जाता है, तब ये उसकी जगह भी लेते हैं।  हेल्पर चाहिए।",
