  "Voices clearer over music and effects: what both speakers share (where voices are) is lifted, the low boom trimmed and the voice band brought forward.  While it's on, the sound goes through the audio converter and comes back as stereo Dolby Digital: a channel takes a second or two longer to start, the rewind buffer isn't used, and sound isn't sent straight to a soundbar (passthrough).": "म्यूज़िक और इफ़ेक्ट के ऊपर आवाज़ें ज़्यादा साफ़ सुनाई देती हैं: दोनों स्पीकर में जो साझा होता है (जहाँ आवाज़ें होती हैं) उसे बढ़ाया जाता है, भारी बूम कम किया जाता है और आवाज़ वाला हिस्सा आगे लाया जाता है।  चालू रहने पर साउंड ऑडियो कन्वर्टर से गुज़रता है और स्टीरियो Dolby Digital में लौटता है: चैनल शुरू होने में एक-दो सेकंड ज़्यादा लगते हैं, रिवाइंड बफ़र इस्तेमाल नहीं होता, और साउंड सीधे साउंडबार को नहीं भेजा जाता (पासथ्रू)।",
  "Wait for the media rescan to finish, then press Yellow.": "मीडिया रीस्कैन पूरा होने तक रुकें, फिर Yellow दबाएं।",
