  "Watchlist finds and the like wait while a movie or episode plays full screen, and show when you stop or leave full screen.  Reminders you set still come on time.": "जब कोई फ़िल्म या एपिसोड फ़ुल स्क्रीन में चल रहा हो, तब वॉचलिस्ट की खोज जैसी सूचनाएं रुकी रहती हैं और आपके रोकने या फ़ुल स्क्रीन से बाहर आने पर दिखती हैं।  आपके लगाए रिमाइंडर फिर भी समय पर आते हैं।",
