  "What you watched on other apps shows as watched here, so Next up and Not watched yet follow along, and what you paused elsewhere is in Continue watching.": "जो आपने दूसरे ऐप में देखा, वह यहां देखा हुआ दिखता है, इसलिए अब अगला और अभी नहीं देखा साथ चलते हैं, और जो आपने कहीं और रोका था वह देखना जारी रखें में मिलता है।",
