  "Year…": "वर्ष…",
  "Yellow": "Yellow",
  "Yellow marks a movie or an episode watched": "Yellow दबाने पर फ़िल्म या एपिसोड देखा हुआ चिह्नित हो जाता है",
  "Yellow marks a movie watched.  For a show, open it.": "Yellow फ़िल्म को देखा हुआ चिह्नित करता है।  शो के लिए उसे खोलें।",
  "Yellow or Back returns to live": "लाइव पर लौटने के लिए Yellow या Back दबाएं",
  "Yes, it's fixed": "हां, ठीक हो गया",
  "Yesterday's Top 10s of the streaming services in your country (FlixPatrol) with the movies and shows your Plex has, best place first, \"#3 on Netflix\" under each.": "आपके देश की स्ट्रीमिंग सेवाओं के कल के Top 10 (FlixPatrol), उन फ़िल्मों और शो के साथ जो आपके Plex में हैं। सबसे ऊपर वाली रैंक पहले, हर एक के नीचे \"Netflix पर #3\" जैसा लिखा होता है।",
  "You have Plex Pass: your servers play anywhere.": "आपके पास Plex Pass है: आपके सर्वर कहीं भी चलते हैं।",
  "You have {x}; the fix is in {y}.": "आपके पास {x} है; फ़िक्स {y} में है।",
  "You missed it:": "आपसे छूट गया:",
  "YouTube app": "YouTube ऐप",
  "Your Plex Watchlist on Home, with the titles your servers have.  More > Add to Watchlist on a movie's page.": "आपकी Plex वॉचलिस्ट होम पर, उन टाइटल के साथ जो आपके सर्वर में हैं।  फ़िल्म के पेज पर और > वॉचलिस्ट में जोड़ें।",
  "Your Plex movies and shows in TiviBro, with their posters, collections, playlists and watched marks.  Once a server and a library are added, Plex gets its own place in the menu, the phone app and the web editor.": "आपकी Plex फ़िल्में और शो TiviBro में, पोस्टर, कलेक्शन, प्लेलिस्ट और देखे हुए निशानों के साथ।  सर्वर और लाइब्रेरी जोड़ते ही मेनू, फ़ोन ऐप और वेब एडिटर में Plex की अपनी जगह बन जाती है।",
  "Your channels, before and after": "आपके चैनल, पहले और बाद में",
  "Your choices: OK on one to change it": "आपकी पसंद: बदलने के लिए किसी पर OK दबाएं",
  "Your files stay where they are": "आपकी फ़ाइलें वहीं रहती हैं जहां हैं",
  "Your groups": "आपके ग्रुप",
  "Your groups first": "पहले आपके ग्रुप",
  "Your groups, renames and hidden items are kept.": "आपके ग्रुप, नाम बदलाव और छिपे हुए आइटम बने रहते हैं।",
  "Your hidden items and renames are kept.": "आपके छिपाए हुए आइटम और बदले हुए नाम रखे गए हैं।",
  "Your internet and your provider's speed, and what that is enough for.": "आपके इंटरनेट और आपके प्रोवाइडर की स्पीड, और वह किसके लिए काफ़ी है।",
  "Your internet speed and your provider's, and what that is enough for.  Stops playback while it runs.": "आपके इंटरनेट और आपके प्रोवाइडर की स्पीड, और वह किसके लिए काफ़ी है।  यह चलते समय प्लेबैक रुक जाता है।",
  "Your internet works; your provider's server doesn't answer": "आपका इंटरनेट चल रहा है; आपके प्रोवाइडर का सर्वर जवाब नहीं दे रहा",
  "Your lists are big for this TV": "आपकी लिस्ट इस TV के लिए बड़ी हैं",
  "Your lists are very big for this TV": "आपकी लिस्ट इस TV के लिए बहुत बड़ी हैं",
  "Your local channels": "आपके लोकल चैनल",
  "Your other playlists' channels always have their own section in the group list, under each playlist's name.  Here you choose where else they show up, with the channels of your first playlist, {x}.": "आपकी दूसरी प्लेलिस्ट के चैनल ग्रुप की सूची में हमेशा अपने अलग सेक्शन में, हर प्लेलिस्ट के नाम के नीचे रहते हैं।  यहां चुनें कि वे और कहां दिखें, आपकी पहली प्लेलिस्ट {x} के चैनलों के साथ।",
  "Your own prefixes and suffixes, TiviMate style, are under Settings > Channel and group names.": "आपके अपने प्रिफ़िक्स और सफ़िक्स, TiviMate स्टाइल में, सेटिंग > चैनल और ग्रुप के नाम में हैं।",
  "Your phone and this TV must be on the same network.  The code only works while this screen is open.": "आपका फ़ोन और यह TV एक ही नेटवर्क पर होने चाहिए।  कोड सिर्फ़ तभी काम करता है जब यह स्क्रीन खुली हो।",
  "Your playlist is not changed.  Turn off to see the original names.": "आपकी प्लेलिस्ट नहीं बदली गई है।  असली नाम देखने के लिए बंद करें।",
  "Your problem report #": "आपकी समस्या रिपोर्ट #",
  "Your problem reports": "आपकी समस्या रिपोर्ट",
  "Your provider answers normally": "आपका प्रोवाइडर सामान्य रूप से जवाब दे रहा है",
  "Your provider has a problem, not TiviBro:": "समस्या आपके प्रोवाइडर में है, TiviBro में नहीं:",
