  "Your watchlist, Trakt's charts, popular lists, a search, or a list's link (like Radarr and Sonarr).  Each goes on the tab for what it holds.": "आपकी वॉचलिस्ट, Trakt के चार्ट, लोकप्रिय लिस्ट, कोई खोज, या किसी लिस्ट का लिंक (Radarr और Sonarr की तरह)।  हर एक उस टैब पर जाती है जिसकी चीज़ें उसमें हैं।",
  "Yours": "आपके अपने",
  "Yours, and the ones friends share with you.": "आपके अपने, और जो दोस्त आपके साथ शेयर करते हैं.",
  "Zoom": "ज़ूम",
