  "After a while with no button pressed (never over a video that plays), the screen goes almost black with a slow, dim clock or picture, so an OLED screen doesn't wear in.  Any button brings TiviBro back.": "कुछ देर तक कोई बटन न दबाने पर (चलते वीडियो के ऊपर कभी नहीं), स्क्रीन लगभग काली हो जाती है और उस पर धीमी, धुंधली घड़ी या तस्वीर दिखती है, ताकि OLED स्क्रीन पर निशान न पड़ें।  कोई भी बटन दबाने पर TiviBro वापस आ जाता है।",
